import {copy,uid,INSTRUMENTS} from './music.js';
import {normalizeSound,SOUND_DEFAULTS} from './sound.js';
import {checksum} from './storage.js';
export const SOUND_BANK_DB='sprout-sound-bank',SOUND_BANK_LIMITS={entries:32,bytes:262144};
const bytes=v=>new TextEncoder().encode(typeof v==='string'?v:JSON.stringify(v)).length;
const exact=(o,keys)=>{if(!o||typeof o!=='object'||Array.isArray(o)||Object.keys(o).some(k=>!keys.includes(k))||keys.some(k=>!Object.hasOwn(o,k)))throw Error('音色收藏字段不完整或包含未知字段')};
function values(instrument,sound){if(typeof instrument!=='string'||!Object.hasOwn(INSTRUMENTS,instrument))throw Error('收藏音源不支持');if(sound===null)return null;exact(sound,Object.keys(SOUND_DEFAULTS[instrument]));const normalized=normalizeSound(instrument,sound);if(Object.keys(normalized).some(k=>sound[k]!==normalized[k]))throw Error('音色参数须使用最多四位小数的有效值');return normalized}
function name(input){if(typeof input!=='string'||!input.trim()||input.length>60)throw Error('音色名称须为 1–60 个字符');return input.trim()}
export function normalizeSoundCollection(input){exact(input,['id','name','instrument','sound','createdAt','archived']);if(typeof input.id!=='string'||!/^[a-zA-Z0-9-]{1,80}$/.test(input.id)||!Number.isSafeInteger(input.createdAt)||input.createdAt<0||typeof input.archived!=='boolean')throw Error('音色收藏标识或时间不正确');return{id:input.id,name:name(input.name),instrument:input.instrument,sound:values(input.instrument,input.sound),createdAt:input.createdAt,archived:input.archived}}
export function soundCompatible(source,target){return typeof source==='string'&&typeof target==='string'&&Object.hasOwn(INSTRUMENTS,source)&&Object.hasOwn(INSTRUMENTS,target)&&(source===target||INSTRUMENTS[source].kind==='tonal'&&INSTRUMENTS[target].kind==='tonal')}
export function collectionForTrack(input,target){const p=normalizeSoundCollection(input);if(p.archived)throw Error('请先恢复归档的音色');if(!soundCompatible(p.instrument,target))throw Error('鼓收藏仅适用于同种鼓；旋律收藏不能用于鼓');if(p.sound===null&&p.instrument!==target)throw Error('原始音色只适用于原音源；不能把另一音源的原始合成复制过来');return p.sound===null?undefined:normalizeSound(target,p.sound)}
export function soundContent(input){return JSON.stringify([input.instrument,values(input.instrument,input.sound)])}
export function exportSoundFile(input){if(!Array.isArray(input)||!input.length||input.length>SOUND_BANK_LIMITS.entries)throw Error('请选择 1–32 个音色导出');const presets=input.map(x=>{const p=normalizeSoundCollection(x);return{name:p.name,instrument:p.instrument,sound:p.sound}}),file={format:'sprout-sounds',version:1,presets};if(bytes(file)>SOUND_BANK_LIMITS.bytes)throw Error('音色文件超过 256 KiB');return file}
export function parseSoundFile(text){if(typeof text!=='string'||bytes(text)>SOUND_BANK_LIMITS.bytes)throw Error('音色文件须为不超过 256 KiB 的文本');let file;try{file=JSON.parse(text)}catch{throw Error('音色文件不是有效 JSON')}exact(file,['format','version','presets']);if(file.format!=='sprout-sounds'||file.version!==1||!Array.isArray(file.presets)||!file.presets.length||file.presets.length>SOUND_BANK_LIMITS.entries)throw Error('音色文件格式 / 版本 / 数量不支持');return file.presets.map(p=>{exact(p,['name','instrument','sound']);return{name:name(p.name),instrument:p.instrument,sound:values(p.instrument,p.sound)}})}
export function planSoundImport(existing,incoming,indices,{duplicates=false,now=Date.now(),idFactory=uid}={}){if(!Array.isArray(existing)||existing.length>SOUND_BANK_LIMITS.entries||!Array.isArray(incoming)||!incoming.length||incoming.length>SOUND_BANK_LIMITS.entries||typeof duplicates!=='boolean'||!Array.isArray(indices)||!indices.length||new Set(indices).size!==indices.length||indices.some(i=>!Number.isInteger(i)||i<0||i>=incoming.length))throw Error('音色导入选择不正确');const entries=existing.map(normalizeSoundCollection),source=parseSoundFile(JSON.stringify({format:'sprout-sounds',version:1,presets:incoming})),keys=new Set(entries.map(soundContent)),ids=new Set(entries.map(p=>p.id)),names=new Set(entries.map(p=>p.name));let skipped=0,added=0;
 for(const i of indices){const p=source[i],key=soundContent(p);if(!duplicates&&keys.has(key)){skipped++;continue}let unique=p.name,n=2;while(names.has(unique))unique=p.name.slice(0,60-(' · '+n).length)+' · '+n++;let id,tries=0;do{if(++tries>50)throw Error('不能分配唯一收藏标识');id=idFactory()}while(ids.has(id));const entry=normalizeSoundCollection({id,name:unique,instrument:p.instrument,sound:p.sound,createdAt:now,archived:false});entries.push(entry);keys.add(key);ids.add(id);names.add(unique);added++}
 if(entries.length>SOUND_BANK_LIMITS.entries||bytes(entries)>SOUND_BANK_LIMITS.bytes)throw Error('音色收藏最多 32 项（含归档） / 256 KiB；这次没有部分导入或自动删除');return{entries,added,skipped};}
export function packSoundCollection(input){const p=normalizeSoundCollection(input),payload=JSON.stringify(p);return{id:p.id,payload,checksum:checksum(payload)}}
export function unpackSoundCollection(r){exact(r,['id','payload','checksum']);if(typeof r.payload!=='string'||bytes(r.payload)>SOUND_BANK_LIMITS.bytes||checksum(r.payload)!==r.checksum)throw Error('音色收藏校验失败，没有自动重置');const p=normalizeSoundCollection(JSON.parse(r.payload));if(p.id!==r.id||JSON.stringify(p)!==r.payload)throw Error('音色收藏记录格式不一致');return p}
export function validateSoundBank(state){if(state==null)return{format:1,revision:0,entries:[]};exact(state,['format','revision','entries']);if(state.format!==1||!Number.isSafeInteger(state.revision)||state.revision<0||!Array.isArray(state.entries)||state.entries.length>SOUND_BANK_LIMITS.entries||bytes(state.entries)>SOUND_BANK_LIMITS.bytes)throw Error('音色收藏库不正确，没有自动重置');const ids=new Set();for(const r of state.entries){const p=unpackSoundCollection(r);if(ids.has(p.id))throw Error('收藏标识重复');ids.add(p.id)}return copy(state)}
export class SoundBankConflict extends Error{constructor(){super('另一页面修改了音色收藏，请重新读取；这次没有覆盖。');this.name='SoundBankConflict'}}
export class SoundBank{
 constructor(adapter,{open,now=()=>Date.now()}={}){this.adapter=adapter;this.open=open;this.now=now;this.entries=[];this.revision=0;this.available=!!adapter;this.error=null;this.queue=Promise.resolve()}
 async load(){try{if(!this.adapter)throw Error('音色收藏存储不可用，草稿仍可导出');const s=validateSoundBank(await this.adapter.read());this.revision=s.revision;this.entries=s.entries.map(unpackSoundCollection);this.available=true;this.error=null;return this.list()}catch(e){this.available=false;this.error=e.message;throw e}}
 mutate(fn){const task=this.queue.then(async()=>{if(!this.available||!this.adapter)throw Error(this.error||'收藏库不可用，请重新读取');const next=fn(copy(this.entries)),records=next.map(packSoundCollection);if(records.length>SOUND_BANK_LIMITS.entries||bytes(records)>SOUND_BANK_LIMITS.bytes)throw Error('收藏已达 32 项 / 256 KiB 上限，没有自动删除');const s=validateSoundBank(await this.adapter.update(this.revision,()=>({format:1,entries:records})));this.revision=s.revision;this.entries=s.entries.map(unpackSoundCollection);return this.list()});this.queue=task.catch(()=>{});return task}
 import(incoming,indices,options){let report;return this.mutate(entries=>{report=planSoundImport(entries,incoming,indices,{...options,now:this.now()});return report.entries}).then(()=>({added:report.added,skipped:report.skipped}))}
 save({name:label,instrument,sound}){return this.import([{name:label,instrument,sound}], [0],{duplicates:true})}
 rename(id,label){const valid=name(label);return this.mutate(entries=>{const p=entries.find(p=>p.id===id);if(!p)throw Error('收藏已不存在');p.name=valid;return entries})}
 archive(id,archived=true){if(typeof archived!=='boolean')throw Error('归档状态不正确');return this.mutate(entries=>{const p=entries.find(p=>p.id===id);if(!p)throw Error('收藏已不存在');p.archived=archived;return entries})}
 get(id){const p=this.entries.find(p=>p.id===id);if(!p)throw Error('收藏已不存在');return copy(p)}
 list(){return copy(this.entries).sort((a,b)=>b.createdAt-a.createdAt)}
 async reload(){await this.queue;try{if(this.open){const next=await this.open();this.adapter?.close?.();this.adapter=next}return await this.load()}catch(e){this.available=false;this.error=e.message;throw e}}
 close(){this.adapter?.close?.()}
}
export class SoundBankDBAdapter{
 constructor(db){this.db=db}close(){this.db.close()}
 read(){return new Promise((resolve,reject)=>{const tx=this.db.transaction('sounds','readonly'),r=tx.objectStore('sounds').get('active');let value;r.onsuccess=()=>value=r.result;tx.oncomplete=()=>resolve(value||null);tx.onabort=tx.onerror=()=>reject(tx.error||Error('读取音色收藏失败'))})}
 update(expected,fn){return new Promise((resolve,reject)=>{const tx=this.db.transaction('sounds','readwrite'),store=tx.objectStore('sounds'),r=store.get('active');let next,error;r.onsuccess=()=>{try{const old=validateSoundBank(r.result);if(old.revision!==expected)throw new SoundBankConflict();next=fn(old);next.revision=expected+1;validateSoundBank(next);store.put(next,'active')}catch(e){error=e;tx.abort()}};tx.oncomplete=()=>resolve(next);tx.onabort=tx.onerror=()=>reject(error||tx.error||Error('收藏保存失败，旧内容保留'))})}
}
export function openSoundBank(factory=globalThis.indexedDB){return new Promise((resolve,reject)=>{if(!factory)return reject(Error('浏览器不支持音色收藏存储'));let settled=false;const r=factory.open(SOUND_BANK_DB,1),timer=setTimeout(()=>{settled=true;reject(Error('音色收藏打开超时'))},2500);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('sounds'))r.result.createObjectStore('sounds')};r.onerror=()=>{if(settled)return;settled=true;clearTimeout(timer);reject(r.error||Error('收藏库不可用'))};r.onsuccess=()=>{if(settled){r.result.close();return}settled=true;clearTimeout(timer);r.result.onversionchange=()=>r.result.close();resolve(new SoundBankDBAdapter(r.result))}})}
export async function createSoundBank(){let adapter;try{adapter=await openSoundBank()}catch{}const bank=new SoundBank(adapter,{open:openSoundBank});try{await bank.load()}catch{}return bank}
